    image_patch = ImagePatch(image)
    players = image_patch.find("ultimate frisbee player")
    discs = image_patch.find("disc")
    fields = image_patch.find("grass field")

    if not players or not discs or not fields:
        return image_patch

    player_disc_pairs = [(player, disc) for player in players for disc in discs if distance(player, disc) < 10]
    valid_pairs = []

    for player, disc in player_disc_pairs:
        player_field_distance = distance(player, fields[0])
        disc_field_distance = distance(disc, fields[0])

        if player_field_distance < disc_field_distance:
            valid_pairs.append((player, disc))

    if not valid_pairs:
        return image_patch

    return max(valid_pairs, key=lambda pair: pair[0].horizontal_center + pair[1].horizontal_center)

